// Game Profile (Takaro Generic Game Protocol v1): who this connector is, the `game.profile`
// capability and the `getGameIcon` answer. The icon is compiled in (game_icon_png.inc, generated by
// tools/gen_game_icon.py from games/conan-exiles/assets/icon-256.png); its revision and size are
// computed from those bytes, never written by hand.
#pragma once
#include "common.h"

#include <string>

namespace conan {

constexpr const char* kGameSlug = "conan-exiles";
constexpr const char* kConnectorName = "takaro-conan-exiles";
constexpr const char* kGameDisplayName = "Conan Exiles";

// The PNG bytes, the first 12 hex characters of their sha256, and the base64 Takaro takes.
const std::string& GameIconPng();
const std::string& GameIconRevision();
std::string Base64(const std::string& bytes);
std::string Sha256Hex(const std::string& bytes);

// The `game.profile` manifest entry. `gameVersion` is the running server build; it is trimmed and
// omitted unless it is 1-32 printable ASCII characters.
std::string GameProfileCapability(const std::string& gameVersion);
// The getGameIcon response payload { revision, data }.
JsonValue GameIconPayload();

}  // namespace conan
